<script setup lang="ts">import {Head,Link} from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; interface Item{id:number;title:string;quantity:number;price:string;shopify_product_id:string|null;shopify_variant_id:string|null;product:{title:string}|null;variant:{title:string;sku:string|null}|null} interface Order{id:number;order_number:string;email:string|null;financial_status:string|null;fulfillment_status:string|null;currency:string;total_price:string;subtotal_price:string;total_tax:string;processed_at:string|null;created_at_shopify:string|null;synced_at:string|null;items:Item[]} defineProps<{order:Order}>(); const financialStatus=(value:string|null)=>({paid:'已付款',pending:'待付款',authorized:'已授权',partially_paid:'部分付款',partially_refunded:'部分退款',refunded:'已退款',voided:'已作废'}[value??'']??value??'未知'); const fulfillmentStatus=(value:string|null)=>({fulfilled:'已履约',partial:'部分履约',restocked:'已重新入库',unfulfilled:'未履约'}[value??'']??value??'未履约'); const money=(value:string)=>Number(value).toFixed(2); const variantLabel=(item:Item)=>item.variant ? `${item.variant.title} · SKU ${item.variant.sku||'—'}` : '未关联本地变体';</script>
<template><Head :title="order.order_number"/><AppLayout :breadcrumbs="[{label:'业务中心'},{label:'订单管理',href:'/orders'},{label:order.order_number}]"><div class="mx-auto max-w-6xl space-y-6"><Link href="/orders" class="text-sm font-semibold text-slate-500">← 返回订单列表</Link><header><p class="text-sm font-semibold text-emerald-700">Shopify 订单</p><h1 class="mt-1 text-3xl font-semibold text-slate-950">{{order.order_number}}</h1><p class="mt-2 text-sm text-slate-500">{{order.email||'访客订单'}}</p></header><section class="grid gap-4 sm:grid-cols-4"><div v-for="item in [['付款状态',financialStatus(order.financial_status)],['履约状态',fulfillmentStatus(order.fulfillment_status)],['订单金额',`${order.currency} ${money(order.total_price)}`],['税费',`${order.currency} ${money(order.total_tax)}`]]" :key="String(item[0])" class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><p class="text-xs text-slate-400">{{item[0]}}</p><p class="mt-2 font-semibold text-slate-900">{{item[1]}}</p></div></section><section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="border-b border-slate-200 px-6 py-5"><h2 class="font-semibold">订单商品</h2></div><div class="divide-y divide-slate-100"><article v-for="item in order.items" :key="item.id" class="grid gap-3 px-6 py-5 sm:grid-cols-[minmax(0,1fr)_100px_160px]"><div><p class="font-semibold text-slate-900">{{item.title}}</p><p class="mt-1 text-xs text-slate-400">{{variantLabel(item)}}</p></div><p class="text-slate-600">× {{item.quantity}}</p><p class="font-semibold">{{order.currency}} {{money(item.price)}}</p></article></div></section></div></AppLayout></template>
